const wkName=s=>new Date(s+'T12:00:00').toLocaleDateString('en-GB',{weekday:'long'});
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
