function docM(row,k){if(row.m[k]!=null&&row.m[k]!=='')return +row.m[k];const all=ST.d.reduce((a,r)=>a+S(Object.values(r.m).map(Number)),0);const mine=S(Object.values(row.m).map(Number));return all?staffedK(k)*mine/all:0}
const docRow=n=>ST.d.find(r=>r.name===n);
// ---------- tabs & chips ----------
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.panel').forEach(p=>p.classList.toggle('active',p.id===b.dataset.panel));window.scrollTo({top:0,behavior:'instant'})});
