const tierCells=v=>TIERS.map(t=>`<td class="${t===1?'t100':''}">${fmt(v*t)}</td>`).join('');
const wdw=js=>D.wd[(js+6)%7];
function dayInfo(ds){const d=new Date(ds+'T12:00:00'),y=d.getFullYear(),m=d.getMonth(),n=new Date(y,m+1,0).getDate();let t=0;for(let i=1;i<=n;i++)t+=wdw(new Date(y,m,i).getDay());return {k:key(y,m),m,f:wdw(d.getDay())/t,n,y,dow:d.getDay()}}
function yearChips(id,cb){return chips(id,YEARS().map(y=>[y,y+(KEYS().filter(k=>k.startsWith(y)).length<12?' (from '+MN[mIdx(KEYS().find(k=>k.startsWith(y)))]+')':'')]),YEARS().includes('2027')?'2027':YEARS()[0],cb)}
// ---------- OVERVIEW ----------
