const a24=yr(2024),a25=yr(2025),a26=yr(2026);const sep26=a26[8]/27*30;
const f26=[null,null,null,null,null,null,null,a26[7],sep26,17.4e6,17.1e6,19.6e6];
const close26=S(a26.slice(0,8))+sep26+17.4e6+17.1e6+19.6e6;
