function renderOv(){const k27=KEYS().filter(k=>k.startsWith('2027')),T=S(k27.map(totK));const kq=KEYS().filter(k=>k>='2026-10'&&k<'2027'),TQ=S(kq.map(totK));
 $('heroStats').innerHTML=[['2026 to date',S(a26),window.__liveOk?'live from Odoo':'ex-VAT actual'],['2026 expected',close26,'trend forecast'],['Q4 2026 target',TQ,'Oct – Dec · 100%'],['2027 target',T,'100% tier']].map(x=>`<div class="hero-stat"><div class="lbl">${x[0]}</div><div class="val">${fm(x[1])}<small>${x[2]}</small></div></div>`).join('');
 $('ladder').innerHTML=TIERS.map(t=>`<div class="rung${t===1?' tot':''}"><div class="l">${Math.round(t*100)}%</div><div class="p">${fm(T*t)}</div></div>`).join('');
 $('yrKpi').innerHTML=`<div class="kpi accent"><div class="kpi-label">2027 target</div><div class="kpi-value">${fm(T)}</div><div class="kpi-sub">${pct(T/close26-1)} on the 2026 forecast · 80% floor ${fm(T*.8)}</div></div>`+
 `<div class="kpi"><div class="kpi-label">Q4 2026 target</div><div class="kpi-value">${fm(TQ)}</div><div class="kpi-sub">80% floor ${fm(TQ*.8)} · forecast ${fm(54.1e6)}</div></div>`+
 [['2025',S(a25),S(a25)/S(a24)-1],['2026 forecast',close26,close26/S(a25)-1]].map(x=>`<div class="kpi"><div class="kpi-label">${x[0]}</div><div class="kpi-value">${fm(x[1])}</div><div class="kpi-sub">${pct(x[2])} on the year before</div></div>`).join('');
 if(typeof Chart==='undefined')return;
 const mt=MN.map((_,i)=>{const k=key(2027,i);return KEYS().includes(k)?totK(k):null}),q26=MN.map((_,i)=>{const k=key(2026,i);return KEYS().includes(k)?totK(k):null});
 const grid=css('--line'),tx=css('--muted');charts.t&&charts.t.destroy();
 charts.t=new Chart($('trend'),{type:'line',data:{labels:MN,datasets:[
  {label:'2024',data:a24,borderColor:'#C3A494',backgroundColor:'#C3A494',tension:.3,pointRadius:2,borderWidth:2},
  {label:'2025',data:a25,borderColor:'#9e6e4a',backgroundColor:'#9e6e4a',tension:.3,pointRadius:2,borderWidth:2},
  {label:'2026',data:a26.map((v,i)=>i<8?v:null),borderColor:'#e8a878',backgroundColor:'#e8a878',tension:.3,pointRadius:3,borderWidth:2.5},
  {label:'2026 forecast',data:f26,borderColor:'#e8a878',borderDash:[5,4],tension:.3,pointRadius:2,borderWidth:2},
  {label:'2026 target',data:q26,borderColor:'#7a5142',backgroundColor:'#7a5142',pointStyle:'rectRot',pointRadius:5,showLine:false},
  {label:'2027 target',data:mt,borderColor:'#58382C',backgroundColor:'#58382C',tension:.3,pointRadius:3,borderWidth:3},
  {label:'2027 at 80%',data:mt.map(v=>v==null?null:v*.8),borderColor:'#58382C',borderDash:[2,4],tension:.3,pointRadius:0,borderWidth:1.5}]},
  options:{maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{labels:{color:tx,boxWidth:12,font:{family:'Inter',size:11}}},tooltip:{callbacks:{label:x=>`${x.dataset.label}: ${fmt(x.raw)}`}}},scales:{x:{grid:{color:grid},ticks:{color:tx}},y:{grid:{color:grid},ticks:{color:tx,callback:v=>v/1e6+'M'}}}}});
 const pal=['#58382C','#9e6e4a','#C3A494','#755644','#957063','#FFD4B4','#5e4025','#b88a6a','#d9bfae','#8c6a58','#e7c9b1','#686665','#c98a2e','#5e8d4a'];const ks=KEYS();
 charts.b&&charts.b.destroy();
 charts.b=new Chart($('tbChart'),{type:'bar',data:{labels:ks.map(mLab),datasets:ST.b.map((r,i)=>({label:r.branch,data:ks.map(k=>+r.m[k]||0),backgroundColor:pal[i%pal.length]}))},options:{maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{color:tx,boxWidth:10,font:{size:10.5}}},tooltip:{callbacks:{label:x=>`${x.dataset.label}: ${fmt(x.raw)}`}}},scales:{x:{stacked:true,grid:{display:false},ticks:{color:tx}},y:{stacked:true,grid:{color:grid},ticks:{color:tx,callback:v=>v/1e6+'M'}}}}});
}
// ---------- ACTUALS ----------
function aperiods(mode){if(mode==='m')return MN.map((x,i)=>[x,[i]]);if(mode==='q')return [0,1,2,3].map(q=>['Q'+(q+1),[q*3,q*3+1,q*3+2]]);return [['Full year',[...Array(12).keys()]]]}
const acYear=chips('acYear',[['2026','2026'],['2025','2025'],['2024','2024']],'2026',renderAc);
const acMode=chips('acMode',MODES,'y',v=>{fillSel($('acPer'),aperiods(v));$('acPer').value=v==='m'?8:v==='q'?2:0;renderAc()});
fillSel($('acPer'),aperiods('y'));$('acPer').onchange=renderAc;
function sumAct(o,y,idx){const r={};idx.forEach(i=>{const x=o[key(y,i)];if(x)for(const k in x)r[k]=(r[k]||0)+x[k]});return r}
function actTable(el,o,y,idx,lab,withT){const c=sumAct(o,y,idx),p=sumAct(o,y-1,idx);const ks=idx.map(i=>key(y,i)).filter(k=>KEYS().includes(k));const hasT=withT&&ks.length;const tb={};if(hasT)ST.b.forEach(r=>tb[r.branch]=sumK(r.m,ks));
 const names=Object.keys({...c,...p}).filter(k=>(c[k]||0)||(p[k]||0)).sort((a,b)=>(c[b]||0)-(c[a]||0));const tc=S(Object.values(c)),tp=S(Object.values(p));let tt=0;
 const body=names.map(k=>{const g=(c[k]||0)/(p[k]||0)-1;let t='';if(hasT){const v=tb[k]||0;tt+=v;const a=v?(c[k]||0)/v:NaN;t=`<td>${v?fmt(v):'—'}</td><td class="${a>=1?'up':a>=.8?'amb':'dn'}">${v?(a*100).toFixed(0)+'%':'—'}</td>`}
  return `<tr><td class="nm">${esc(k)}</td><td class="t100">${fmt(c[k]||0)}</td><td>${fmt(p[k]||0)}</td><td class="${g>=0?'up':'dn'}">${p[k]?pct(g):'new'}</td><td>${tc?((c[k]||0)/tc*100).toFixed(1)+'%':'—'}</td>${t}</tr>`}).join('');
 el.innerHTML=`<thead><tr><th>${lab}</th><th>${y}</th><th>${y-1}</th><th>Growth</th><th>Share</th>${hasT?'<th>Target</th><th>Achieved</th>':''}</tr></thead><tbody>${body}<tr class="total"><td>Total</td><td>${fmt(tc)}</td><td>${fmt(tp)}</td><td>${pct(tc/tp-1)}</td><td>100%</td>${hasT?`<td>${fmt(tt)}</td><td>${tt?(tc/tt*100).toFixed(0)+'%':'—'}</td>`:''}</tr></tbody>`}
function renderAc(){const y=+acYear(),idx=aperiods(acMode())[+$('acPer').value][1];actTable($('acBr'),D.act,y,idx,'Branch',true);actTable($('acSv'),D.actg,y,idx,'Service');actTable($('acPt'),D.actp,y,idx,'Product type')}
// ---------- BRANCH TARGETS ----------
let tbYear,tbMode,tbBrand,tbTier;
function setupTb(){tbYear=yearChips('tbYear',()=>{fillSel($('tbPer'),tperiods(tbYear(),tbMode()));renderTb()});
 tbMode=chips('tbMode',[...MODES,['d','Day'],['g','All months']],'m',v=>{$('tbPer').hidden=v==='d'||v==='g';$('tbDay').hidden=v!=='d';$('tbTier').hidden=v!=='g';$('tbOne').hidden=v!=='g';if(v!=='d'&&v!=='g')fillSel($('tbPer'),tperiods(tbYear(),v));renderTb()});
 tbTier=chips('tbTier',TIERS.map(x=>[String(x),Math.round(x*100)+'%']),'1',renderTb);
 const cur=$('tbOne').value;$('tbOne').innerHTML='<option value="">All branches, all months</option>'+ST.b.map(r=>`<option>${esc(r.branch)}</option>`).join('');$('tbOne').value=ST.b.some(r=>r.branch===cur)?cur:'';
 tbBrand=chips('tbBrand',[['all','All'],['Nouvelage','Nouvelage'],['ZAT','ZAT']],'all',renderTb);fillSel($('tbPer'),tperiods(tbYear(),'m'))}
$('tbPer').onchange=()=>renderTb();$('tbOne').onchange=()=>renderTb();$('tbDay').onchange=()=>renderTb();
function renderTb(){const mode=tbMode(),bf=tbBrand();const rows=ST.b.filter(r=>bf==='all'||r.brand===bf);let lab,vals;
 if(mode==='g'){const ks=KEYS().filter(k=>k.startsWith(tbYear())),tr=+tbTier(),one=$('tbOne').value;$('tbTitle').textContent=one?one+' month by month':'All branches, all months';
  if(one){const r=ST.b.find(x=>x.branch===one);const yt=sumK(r.m,ks);$('tbT').innerHTML=`<thead><tr><th>${esc(one)} · ${tbYear()}</th>${tierHead()}<th>Of year</th><th>Per day</th></tr></thead><tbody>`+ks.map(k=>{const v=+r.m[k]||0,d=new Date(+k.slice(0,4),mIdx(k)+1,0).getDate();return `<tr><td class="nm">${MN[mIdx(k)]} ${k.slice(0,4)}</td>${tierCells(v)}<td>${yt?(v/yt*100).toFixed(1):0}%</td><td>${fmt(v/d)}</td></tr>`}).join('')+`<tr class="total"><td>Total</td>${tierCells(yt)}<td>100%</td><td></td></tr></tbody>`;return}
  const cols=ks.map(k=>`<th>${mLab(k)}</th>`).join('');const tot=ks.map(k=>rows.reduce((a,r)=>a+(+r.m[k]||0),0));
  $('tbT').innerHTML=`<thead><tr><th>Branch · ${Math.round(tr*100)}%</th>${cols}<th>Total</th></tr></thead><tbody>`+rows.slice().sort((a,b)=>sumK(b.m,ks)-sumK(a.m,ks)).map(r=>`<tr><td class="nm">${esc(r.branch)}<span class="m">${esc(r.brand)}</span></td>${ks.map(k=>`<td>${fmt((+r.m[k]||0)*tr)}</td>`).join('')}<td class="t100">${fmt(sumK(r.m,ks)*tr)}</td></tr>`).join('')+`<tr class="total"><td>Total</td>${tot.map(v=>`<td>${fmt(v*tr)}</td>`).join('')}<td>${fmt(S(tot)*tr)}</td></tr></tbody>`;return}
 if(mode==='d'){const ds=$('tbDay').value;const I=dayInfo(ds);vals=rows.map(r=>[r,(+r.m[I.k]||0)*I.f]);lab=longDate(ds);$('tbTitle').textContent=wkName(ds)+' target by branch'}
 else{const p=tperiods(tbYear(),mode)[+$('tbPer').value]||tperiods(tbYear(),mode)[0];vals=rows.map(r=>[r,sumK(r.m,p[1])]);lab=p[0];$('tbTitle').textContent='Targets by branch'}
 const tot=S(vals.map(v=>v[1]));
 $('tbT').innerHTML=`<thead><tr><th>${esc(lab)}</th>${tierHead()}<th>Share</th></tr></thead><tbody>`+vals.sort((a,b)=>b[1]-a[1]).map(([r,v])=>`<tr><td class="nm">${esc(r.branch)}<span class="m">${esc(r.brand)}</span></td>${tierCells(v)}<td>${tot?(v/tot*100).toFixed(1):0}%</td></tr>`).join('')+`<tr class="total"><td>Total</td>${tierCells(tot)}<td>100%</td></tr></tbody>`}
