const avgTG=(()=>{const g=D.G.map(()=>0);let t=0;for(const b in D.TG)D.TG[b].forEach(r=>r.forEach((v,i)=>{g[i]+=v;t+=v}));return g.map(v=>v/t)})();
const avgTP=(()=>{const o={};D.G.forEach(G=>{const acc={};for(const b in D.TP){const m=D.TP[b][G]||{};for(const k in m)acc[k]=(acc[k]||0)+m[k]}const s=S(Object.values(acc));for(const k in acc)acc[k]/=s||1;o[G]=acc});return o})();
function groupSplit(b,i,v){const r=D.TG[b]&&D.TG[b][i];if(r){const s=S(r);if(s>0)return r.map(x=>x/s*v)}const seas=D.TG['CFC']?D.TG['CFC'][i]:null;return avgTG.map(x=>x*v)}
