function svcSplit(rows,ks){const g={},p={};rows.forEach(r=>ks.forEach(k=>{groupSplit(r.branch,mIdx(k),+r.m[k]||0).forEach((v,gi)=>{const G=D.G[gi];g[G]=(g[G]||0)+v;const mix=(D.TP[r.branch]&&D.TP[r.branch][G])||avgTP[G];for(const x in mix)p[x]=(p[x]||0)+v*mix[x]})}));return {g,p}}
