$('tsPer').onchange=()=>renderTs();$('tsBr').onchange=()=>renderTs();
const ptGroup=(()=>{const o={};D.G.forEach(G=>{Object.keys(avgTP[G]||{}).forEach(k=>{if(!o[k])o[k]=G})});return o})();
function renderTs(){const br=$('tsBr').value,rows=ST.b.filter(r=>!br||r.branch===br),p=tperiods(tsYear(),tsMode())[+$('tsPer').value]||tperiods(tsYear(),tsMode())[0];const {g,p:pp}=svcSplit(rows,p[1]);const tg=S(Object.values(g));
 const days=S(p[1].map(k=>new Date(+k.slice(0,4),+k.slice(5),0).getDate()));const Gs=Object.keys(g).filter(x=>g[x]>500).sort((a,b)=>g[b]-g[a]);const top=Gs[0];
 $('tsLab').textContent=(br||'All branches')+' · '+p[0];
 $('tsKpi').innerHTML=`<div class="kpi accent"><div class="kpi-label">Service target · ${esc(p[0])}</div><div class="kpi-value">${fmt(tg)}</div><div class="kpi-sub">${esc(br||'All branches')} · 100% tier</div></div>`+
  `<div class="kpi"><div class="kpi-label">Commission floor</div><div class="kpi-value">${fm(tg*.8)}</div><div class="kpi-sub">80% of target</div></div>`+
  `<div class="kpi"><div class="kpi-label">Biggest service</div><div class="kpi-value">${top?esc(top):'—'}</div><div class="kpi-sub">${top?(g[top]/tg*100).toFixed(0)+'% of the target':''}</div></div>`+
  `<div class="kpi"><div class="kpi-label">Per day</div><div class="kpi-value">${fm(days?tg/days:0)}</div><div class="kpi-sub">across ${days} days</div></div>`;
 $('tsCards').innerHTML=Gs.map(G=>{const pts=Object.keys(pp).filter(k=>ptGroup[k]===G&&pp[k]>500).sort((a,b)=>pp[b]-pp[a]);const sh=g[G]/tg;
  return `<div class="ts-card"><h4>${esc(G)}<span class="pctb n" title="Share of the total target">${(sh*100).toFixed(1)}% of total</span></h4><div class="ts-lab">Target (100%)</div><div class="ts-big">${fmt(g[G])}</div><div class="ts-tiers"><span><b>80%</b> commission starts · ${fmt(g[G]*.8)}</span><span><b>Per day</b> · ${fmt(days?g[G]/days:0)}</span></div><div class="ts-bar"><i style="width:${Math.min(100,sh*100/(g[top]/tg)).toFixed(1)}%"></i></div>`+
  pts.map(k=>`<div class="ts-pt"><span>${esc(k)}</span><span>${fmt(pp[k])} · ${(pp[k]/g[G]*100).toFixed(0)}%</span></div>`).join('')+'</div>'}).join('');
 $('tsG').innerHTML=`<thead><tr><th>${esc(p[0])}</th>${tierHead()}<th>Share</th></tr></thead><tbody>`+Gs.map(G=>{const pts=Object.keys(pp).filter(k=>ptGroup[k]===G&&pp[k]>500).sort((a,b)=>pp[b]-pp[a]);
  return `<tr class="grp"><td>${esc(G)}</td>${TIERS.map(x=>`<td>${fmt(g[G]*x)}</td>`).join('')}<td>${(g[G]/tg*100).toFixed(1)}%</td></tr>`+pts.map(k=>`<tr><td class="nm" style="padding-left:26px">${esc(k)}</td>${tierCells(pp[k])}<td>${(pp[k]/tg*100).toFixed(1)}%</td></tr>`).join('')}).join('')+`<tr class="total"><td>Total</td>${tierCells(tg)}<td>100%</td></tr></tbody>`}
