const topSvc=d=>{if(!d||!d.mix)return '';const e=Object.entries(d.mix).sort((a,b)=>b[1]-a[1])[0];return e?e[0]:''};
function monthHours(d,y,m){const n=new Date(y,m+1,0).getDate();let h=0;for(let i=1;i<=n;i++){((d.roster||{})[new Date(y,m,i).getDay()]||[]).forEach(x=>h+=x[1])}return h}
function docDay(name,ds,hours){const r=docRow(name);if(!r)return null;const I=dayInfo(ds);const t=docM(r,I.k);const d=docBy(name);const mh=d?monthHours(d,I.y,I.m):0;return mh?t*hours/mh:t/I.n}
