  const tr=n+2;ws['A'+tr]={t:'s',v:totalLabel};for(let c=fixed;c<fixed+ks.length+2;c++)ws[col(c)+tr]={t:'n',f:`SUM(${col(c)}2:${col(c)}${n+1})`};
