 D.rosterB=R;const byDoc={};for(const br in R)for(const dw in R[br])R[br][dw].forEach(s=>{const o=byDoc[s[0]]=byDoc[s[0]]||{roster:{},hrs:{},dep:s[4]};(o.roster[dw]=o.roster[dw]||[]).push([br,s[1],s[2],s[3],s[4]]);o.hrs[br]=(o.hrs[br]||0)+s[1]});
