// ---------- SORT BY ANY COLUMN, IN EVERY TABLE ----------
const SORTS={};
function tKey(tb){if(tb.id)return tb.id;const host=tb.closest('[id]');const all=host?[...host.querySelectorAll('table.tg-t')]:[];return (host?host.id:'x')+'#'+all.indexOf(tb)}
function cellVal(td){if(!td)return null;const t=(td.innerText||'').split('\n')[0].trim();if(!t||t==='—'||t==='-')return null;
 const m=t.replace(/,/g,'').match(/^([+\-]?\d+(\.\d+)?)\s*(%|M|K|h)?/i);if(m){let v=parseFloat(m[1]);const u=(m[3]||'').toUpperCase();if(u==='M')v*=1e6;else if(u==='K')v*=1e3;return v}return t.toLowerCase()}
function cmp(a,b,dir){if(a===null&&b===null)return 0;if(a===null)return 1;if(b===null)return -1;const r=(typeof a==='number'&&typeof b==='number')?a-b:String(a).localeCompare(String(b));return dir==='asc'?r:-r}
let sortObs=null;
function applySort(tb){const st=SORTS[tKey(tb)];const body=tb.tBodies[0];if(!st||!body)return;const ths=tb.tHead?[...tb.tHead.rows[0].cells]:[];ths.forEach((th,i)=>{if(i===st.col)th.setAttribute('data-sort',st.dir);else th.removeAttribute('data-sort')});
 const rows=[...body.rows];const total=rows.filter(r=>r.classList.contains('total'));const rest=rows.filter(r=>!r.classList.contains('total'));const hasGrp=rest.some(r=>r.classList.contains('grp'));
 const key=r=>{let c=0,idx=0;for(const cell of r.cells){if(c===st.col)return cellVal(cell);c+=cell.colSpan||1;idx++}return null};
 let ordered;if(hasGrp){const blocks=[];let cur=null;rest.forEach(r=>{if(r.classList.contains('grp')){cur={h:r,k:[]};blocks.push(cur)}else if(cur)cur.k.push(r);else blocks.push({h:null,k:[r]})});
  blocks.forEach(b=>b.k.sort((x,y)=>cmp(key(x),key(y),st.dir)));blocks.sort((x,y)=>x.h&&y.h?cmp(key(x.h),key(y.h),st.dir):0);ordered=blocks.flatMap(b=>b.h?[b.h,...b.k]:b.k)}
 else ordered=rest.slice().sort((x,y)=>cmp(key(x),key(y),st.dir));
 if(sortObs)sortObs.disconnect();[...ordered,...total].forEach(r=>body.appendChild(r));if(sortObs)sortObs.observe(document.body,{childList:true,subtree:true})}
document.addEventListener('click',e=>{const th=e.target.closest('table.tg-t thead th');if(!th||th.closest('.cp-t'))return;const tb=th.closest('table');let col=0;for(const c of th.parentNode.cells){if(c===th)break;col+=c.colSpan||1}
 const k=tKey(tb),cur=SORTS[k];let dir;if(cur&&cur.col===col)dir=cur.dir==='desc'?'asc':'desc';else{const r=[...(tb.tBodies[0]||{rows:[]}).rows].find(r=>!r.classList.contains('grp')&&!r.classList.contains('total'));let c=0,v=null;if(r)for(const cell of r.cells){if(c===col){v=cellVal(cell);break}c+=cell.colSpan||1}dir=typeof v==='string'?'asc':'desc'}SORTS[k]={col,dir};applySort(tb)});
let sortPending=false;sortObs=new MutationObserver(()=>{if(sortPending)return;sortPending=true;requestAnimationFrame(()=>{sortPending=false;document.querySelectorAll('table.tg-t').forEach(tb=>{if(SORTS[tKey(tb)])applySort(tb)})})});
sortObs.observe(document.body,{childList:true,subtree:true});

