const whSort=mkChips('whSort',[['ach','Achieved'],['net','Collected'],['tgt','Target'],['name','Name']],'ach',()=>sortWhCards());$('whSortSlot').appendChild(whSort);
let WH_DIR={ach:'desc',net:'desc',tgt:'desc',name:'asc'};whSort.addEventListener('click',e=>{const c=e.target.closest('.chip');if(c&&c.dataset.v===whSort._last){WH_DIR[c.dataset.v]=WH_DIR[c.dataset.v]==='asc'?'desc':'asc';sortWhCards()}if(c)whSort._last=c.dataset.v},true);whSort._last='ach';
function sortWhCards(){const box=$('whBr');const cards=[...box.querySelectorAll(':scope > .branch-block')];if(cards.length<2)return;const k=whSort.get(),dir=WH_DIR[k];
 const v=c=>{const h=c.querySelector('.branch-head');if(k==='name')return (h.querySelector('.bh-name')||{}).textContent||'';const cols=[...h.querySelectorAll('.wh-col')];const num=el=>el?parseFloat(el.textContent.replace(/[^0-9.\-]/g,''))||0:0;
  if(k==='ach'){const p=h.querySelector('.wh-pct');return p?num(p):-1}if(k==='net')return WR?num(cols[0]&&cols[0].querySelector('.wh-big')):0;return WR?num(cols[1]&&cols[1].querySelector('.wh-mid')):num(cols[0]&&cols[0].querySelector('.wh-big'))};
 cards.sort((a,b)=>{const x=v(a),y=v(b);const r=typeof x==='string'?x.localeCompare(y):x-y;return dir==='asc'?r:-r});
 if(sortObs)sortObs.disconnect();cards.forEach(c=>box.appendChild(c));if(sortObs)sortObs.observe(document.body,{childList:true,subtree:true})}
