function badgeify(root){(root||document).querySelectorAll('table.tg-t td').forEach(td=>{if(td.dataset.bd)return;const first=td.firstChild;if(!first||first.nodeType!==3)return;const m=first.nodeValue.trim().match(/^(\d+(\.\d+)?)%$/);if(!m)return;
 const cls=td.classList.contains('up')?'g':td.classList.contains('amb')?'a':td.classList.contains('dn')?'r':null;let c=cls;if(!c){const v=parseFloat(m[1]);const head=td.closest('table').tHead;if(!head)return;let ci=0;for(const x of td.parentNode.cells){if(x===td)break;ci+=x.colSpan||1}let hc=0,th=null;for(const h of head.rows[0].cells){if(hc===ci){th=h;break}hc+=h.colSpan||1}
  if(!th)return;if(/share|of year/i.test(th.textContent))c='n';else if(/achiev/i.test(th.textContent))c=v>=100?'g':v>=80?'a':'r';else return}
 td.dataset.bd='1';const s=document.createElement('span');s.className='pctb '+c;s.textContent=first.nodeValue.trim();td.replaceChild(s,first)})}
const _sortObsCb=()=>{if(sortObs)sortObs.disconnect();badgeify();if(sortObs)sortObs.observe(document.body,{childList:true,subtree:true})};
let bdPending=false;new MutationObserver(()=>{if(bdPending)return;bdPending=true;requestAnimationFrame(()=>{bdPending=false;_sortObsCb()})}).observe(document.body,{childList:true,subtree:true});
badgeify();

