const tpShare=n=>{const d=docBy(n)||D.docs.find(x=>wn(x.name)===wn(n));if(!d||!d.roster)return {};const h={};for(const dw in d.roster)d.roster[dw].forEach(s=>h[s[0]]=(h[s[0]]||0)+s[1]);const T=S(Object.values(h));const o={};for(const b in h)o[b]=T?h[b]/T:0;return o};
